function s(){document.querySelectorAll(".carousel-wrapper").forEach(t=>{const e=t.querySelector(".mobile-carousel"),r=t.querySelector(".carousel-btn.prev"),o=t.querySelector(".carousel-btn.next");if(!e||!r||!o)return;const n=()=>{const c=e.firstElementChild;return c?c.offsetWidth+19:window.innerWidth*.85};r.addEventListener("click",()=>{e.scrollBy({left:-n(),behavior:"smooth"})}),o.addEventListener("click",()=>{e.scrollBy({left:n(),behavior:"smooth"})})})}export{s as i};
